local root=assert(os.getenv('QCOM_VP_PROBE_ROOT'))..'/'
platform={moduletype='Container',qemu_inst_mgr={moduletype='QemuInstanceManager'},
    apss_instance={moduletype='QemuInstance',args={'&qemu_inst_mgr','AARCH64'},accel='tcg',
        sync_policy='multithread-quantum',qemu_args='-d in_asm -D '..root..'producer.log'},
    apss_router={moduletype='router'},
    apss_access={moduletype='AccessMonitor',initiator_socket={bind='&apss_router.target_socket'}},
    apss={moduletype='cpu_arm_cortexA53',args={'&apss_instance'},rvbar=0x300000,
        has_el3=true,has_el2=true,mem={bind='&apss_access.target_socket'}},
    rom={moduletype='gs_memory',read_only=true,
        target_socket={address=0x300000,size=0x1000,bind='&apss_router.initiator_socket'},
        load={{bin_file=root..'producer.bin',offset=0}}},
    plls={moduletype='qcom,gcc-taycan-eko-t-pll-v1',reference_hz=19200000,pll_count=12,vote_count=3,
        coarse_calibration_mask=0x800,virtual_coarse_calibration_code=13,
        target_socket={address=0x100000,size=0xb038,bind='&apss_router.initiator_socket'},
        vote_socket={address=0x152020,size=0xa004,bind='&apss_router.initiator_socket'}},
    runtime_root={moduletype='qcom,cpucp-runtime-rcg-v1',pll_path='plls',primary_selector=1,
        target_socket={address=0x200900,size=0x14,bind='&apss_router.initiator_socket'},
        runtime_socket={address=0x200940,size=0x28,bind='&apss_router.initiator_socket'}},
    test_divider={moduletype='qcom,clock-integer-divider-v1',pll_path='plls',
        field_shift=16,field_width=9,
        target_socket={address=0x200800,size=4,bind='&apss_router.initiator_socket'}},
    divider_branch={moduletype='qcom,clock-branch-v1',source_path='test_divider',
        target_socket={address=0x200804,size=4,bind='&apss_router.initiator_socket'}},
    external_pll={moduletype='qcom,gcc-taycan-eko-t-pll-v1',reference_hz=19200000,
        external_vote_path='plls',external_vote_mask=1,
        target_socket={address=0x120000,size=0x38,bind='&apss_router.initiator_socket'}},
    external_root={moduletype='qcom,rcg-v1',pll_path='external_pll',primary_selector=1,
        target_socket={address=0x200500,size=0x14,bind='&apss_router.initiator_socket'}},
    even_root={moduletype='qcom,rcg-v1',pll_path='plls',
        crystal_selector=0,primary_selector=1,primary_even_selector=6,
        target_socket={address=0x200000,size=0x14,bind='&apss_router.initiator_socket'}},
    main_root={moduletype='qcom,rcg-v1',pll_path='plls',
        crystal_selector=0,primary_selector=1,primary_even_selector=6,
        main_sources='3 11;7 4',
        target_socket={address=0x200100,size=0x14,bind='&apss_router.initiator_socket'}},
    dfs_root={moduletype='qcom,rcg-dfs-v1',pll_path='plls',mnd_width=16,
        crystal_selector=0,primary_selector=1,primary_even_selector=6,
        target_socket={address=0x200700,size=0xfc,bind='&apss_router.initiator_socket'}},
    isolated_domain={moduletype='qcom,gdsc-v1',virtual_supply=true,
        target_socket={address=0x200600,size=8,bind='&apss_router.initiator_socket'}},
    crystal={moduletype='qcom,virtual-always-on-clock-v1'},
    symbol_mux={moduletype='qcom,symbol-clock-mux-v1',phy_path='even_root',
        crystal_path='crystal',reset_selector=0,
        target_socket={address=0x200300,size=4,bind='&apss_router.initiator_socket'}},
    branch_votes_0={moduletype='qcom,clock-vote-bank-v1',mask0=1,mask1=2,
        target_socket={address=0x200400,size=0x1c,bind='&apss_router.initiator_socket'}},
    branch_votes_1={moduletype='qcom,clock-vote-bank-v1',mask0=4,
        target_socket={address=0x200440,size=4,bind='&apss_router.initiator_socket'}},
    branch_votes_2={moduletype='qcom,clock-vote-bank-v1',mask0=8,
        target_socket={address=0x200480,size=4,bind='&apss_router.initiator_socket'}},
    branch={moduletype='qcom,clock-branch-v1',source_path='symbol_mux',
        hardware_control=true,continuous_demand=true,
        vote_path_0='branch_votes_0',vote_offset_0=0,vote_mask_0=1,
        vote_path_1='branch_votes_1',vote_offset_1=0,vote_mask_1=4,
        vote_path_2='branch_votes_2',vote_offset_2=0,vote_mask_2=8,
        target_socket={address=0x200200,size=4,bind='&apss_router.initiator_socket'}}}
